package com.campusnova.service;
import com.campusnova.config.CollegeProfile; import com.campusnova.model.OfficialKnowledge; import com.campusnova.repository.OfficialKnowledgeRepository; import org.springframework.stereotype.Service; import java.io.*; import java.net.*; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.*; import java.util.regex.*;
/** Admin-triggered importer; student chat never calls the official site. */
@Service public class OfficialKnowledgeImportService { private final OfficialKnowledgeRepository repository; private final CollegeProfile profile; public OfficialKnowledgeImportService(OfficialKnowledgeRepository r,CollegeProfile p){repository=r;profile=p;} public List<OfficialKnowledge> importCorePages(){String[] paths={"","college/","departments/","programs/","admission-keam/","admission-procedure/","central-library/","bus-service/","hostel/","administrative-wing/","principal/","college-map/","placement-cell/","login/"};List<OfficialKnowledge> result=new ArrayList<OfficialKnowledge>();for(String path:paths){try{result.add(importUrl(profile.getOfficialDomain()+path));}catch(IOException ignored){/* one unavailable page must not prevent the rest of a safe import */}}return result;} public OfficialKnowledge importUrl(String source) throws IOException { URL url=new URL(source); URL allowed=new URL(profile.getOfficialDomain());if(!url.getHost().equalsIgnoreCase(allowed.getHost())||!("https".equalsIgnoreCase(url.getProtocol())||"http".equalsIgnoreCase(url.getProtocol())))throw new IllegalArgumentException("Only the configured official LBSCEK domain can be imported");HttpURLConnection connection=(HttpURLConnection)url.openConnection();connection.setConnectTimeout(8000);connection.setReadTimeout(12000);connection.setRequestProperty("User-Agent","CampusNova official knowledge importer/1.0");String html=read(connection);String title=extract(html,"(?is)<title[^>]*>(.*?)</title>");String text=html.replaceAll("(?is)<script.*?</script>|<style.*?</style>|<!--.*?-->"," ").replaceAll("(?is)<[^>]+>"," ").replaceAll("&nbsp;|&#8211;"," ").replaceAll("&amp;","&").replaceAll("\\s+"," ").trim();if(text.length()>11000)text=text.substring(0,11000);OfficialKnowledge entry=repository.findBySourceUrl(source).orElse(new OfficialKnowledge(source,clean(title),"WEB_PAGE",categoryFor(source),text));entry.setTitle(clean(title));entry.setCategory(categoryFor(source));entry.setExtractedText(text);entry.setOfficialSource(true);entry.setVerified(true);entry.setActive(true);entry.setChecksum(hash(text));return repository.save(entry);} private String read(HttpURLConnection c)throws IOException{try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return new String(out.toByteArray(),StandardCharsets.UTF_8);}} private String extract(String text,String regex){Matcher m=Pattern.compile(regex).matcher(text);return m.find()?m.group(1):"LBSCEK official page";} private String clean(String value){return value.replaceAll("(?is)<[^>]+>"," ").replaceAll("\\s+"," ").trim();} private String categoryFor(String url){String s=url.toLowerCase();if(s.contains("library"))return "Library";if(s.contains("bus"))return "Transport";if(s.contains("hostel"))return "Hostel";if(s.contains("placement"))return "Placements";if(s.contains("admission"))return "Admissions";if(s.contains("principal")||s.contains("administrative"))return "Administration";if(s.contains("department")||s.contains("program"))return "Academics";return "College Information";} private String hash(String value){try{byte[] h=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte x:h)b.append(String.format("%02x",x));return b.toString();}catch(Exception e){return "";}} }
